function FolioPaymentDialog({kind,snapshot,maximumMinor,onClose,onSave}:{kind:string;snapshot:any;maximumMinor?:number;onClose:()=>void;onSave:(v:any)=>Promise<void>}){
 const config=recordsOf(snapshot,'paymentConfig')[0]||{methods:['CASH']};const methods=config.methods||['CASH'];const [method,setMethod]=useState(methods[0]||'CASH');const [amount,setAmount]=useState(maximumMinor?maximumMinor/100:0);const [cash,setCash]=useState(maximumMinor?maximumMinor/100:0);const [reference,setReference]=useState('');const account=config.mpesaAccounts?.[0]?.number||'';
 const amountMinor=Math.round(Number(amount||0)*100);const payload:any={amountMinor,method};if(method==='CASH')payload.cashTenderedMinor=Math.round(Number(cash||0)*100);else{payload.reference=reference;payload.manuallyConfirmed=true;if(method==='MPESA')payload.account=account}
 return <ActionDialog title={kind==='DEPOSIT'?'Record guest deposit':'Settle folio'} onClose={onClose}><form className="space-y-3" onSubmit={e=>{e.preventDefault();void onSave(payload)}}><label>Method<select className={fieldClass} value={method} onChange={e=>setMethod(e.target.value)}>{methods.map((m:string)=><option key={m}>{m}</option>)}</select></label><label>Amount (KES)<input className={fieldClass} type="number" min="0.01" max={maximumMinor?maximumMinor/100:undefined} step="0.01" value={amount} onChange={e=>{setAmount(Number(e.target.value));setCash(Number(e.target.value))}}/></label>{method==='CASH'?<label>Cash tendered (KES)<input className={fieldClass} type="number" min={amount} step="0.01" value={cash} onChange={e=>setCash(Number(e.target.value))}/></label>:<><label>{method==='MPESA'?'Transaction code':'External approval reference'}<input className={fieldClass} value={reference} onChange={e=>setReference(e.target.value.toUpperCase())}/></label>{method==='MPESA'&&<label>M-Pesa account<input disabled className={fieldClass} value={account}/></label>}<p className="text-xs text-amber-200">This action records funds only after you manually verify the external receipt.</p></>}<button disabled={amountMinor<=0||(maximumMinor!==undefined&&amountMinor>maximumMinor)||(method!=='CASH'&&!reference.trim())} className={primaryButtonClass}>{kind==='DEPOSIT'?'Record deposit':'Record settlement'}</button></form></ActionDialog>
}

function DepositRefundDialog({maximumMinor,onClose,onSave}:{maximumMinor:number;onClose:()=>void;onSave:(v:any)=>Promise<void>}){
 const [method,setMethod]=useState('CASH');const [amount,setAmount]=useState(maximumMinor/100);const [reference,setReference]=useState('');const [reason,setReason]=useState('');
 const amountMinor=Math.round(amount*100);const payload:any={amountMinor,method,reason};if(method!=='CASH'){payload.reference=reference;payload.manuallyConfirmed=true}
